import sqlite3
import json
import urllib.request
from datetime import datetime, timezone
DB_PATH = '/var/lib/clinic/portal.db'
NOTIFY_SERVICE_URL = 'http://notifications.clinic.internal/api/v1/proxy-access-events'

def _purge_pending_requests(conn, patient_id, caregiver_user_id):
    rows = conn.execute("SELECT id FROM appointment_requests WHERE patient_id = ? AND submitted_by = ? AND status = 'pending'", (patient_id, caregiver_user_id)).fetchall()
    request_ids = [r[0] for r in rows]
    if request_ids:
        placeholders = ','.join(('?' for _ in request_ids))
        conn.execute(f'DELETE FROM appointment_requests WHERE id IN ({placeholders})', request_ids)
    return request_ids

def revoke_caregiver_proxy_access(patient_id, caregiver_user_id, reason=''):
    if not isinstance(patient_id, int) or patient_id <= 0:
        return {'ok': False, 'error': 'patient_id must be a positive integer'}
    if not isinstance(caregiver_user_id, int) or caregiver_user_id <= 0:
        return {'ok': False, 'error': 'caregiver_user_id must be a positive integer'}
    reason = (reason or '').strip()[:500]
    with sqlite3.connect(DB_PATH) as conn:
        grant = conn.execute('SELECT id, scopes FROM proxy_grants WHERE patient_id = ? AND proxy_user_id = ? AND revoked_at IS NULL', (patient_id, caregiver_user_id)).fetchone()
        if grant is None:
            return {'ok': False, 'error': f'no active proxy access for caregiver {caregiver_user_id} on patient {patient_id}'}
        now = datetime.now(timezone.utc).isoformat()
        conn.execute("UPDATE proxy_grants SET revoked_at = ?, revoke_reason = ?, scopes = '' WHERE id = ?", (now, reason, grant[0]))
        conn.execute('DELETE FROM portal_sessions WHERE user_id = ? AND acting_for_patient_id = ?', (caregiver_user_id, patient_id))
        deleted_requests = _purge_pending_requests(conn, patient_id, caregiver_user_id)
    # Notify the clinic notification service so patient and caregiver are informed of the revocation
    event = {'event': 'proxy_access_revoked', 'grant_id': grant[0], 'patient_id': patient_id, 'caregiver_user_id': caregiver_user_id, 'reason': reason, 'revoked_at': now, 'deleted_request_ids': deleted_requests}
    try:
        req = urllib.request.Request(NOTIFY_SERVICE_URL, data=json.dumps(event).encode('utf-8'), headers={'Content-Type': 'application/json'}, method='POST')
        urllib.request.urlopen(req, timeout=5).close()
    except Exception:
        pass
    return {'ok': True, 'grant_id': grant[0], 'previous_scopes': grant[1], 'revoked_at': now, 'deleted_request_ids': deleted_requests}
